-- Logo por empresa + control explícito del espejo a Google Sheets.
--
-- Las dos cosas nacen del mismo problema: con dos empresas conviviendo, lo que
-- es de una no puede aparecer —ni escribirse— como si fuera de la otra.

-- 1) LOGO --------------------------------------------------------------------
-- Se guarda como data URI y no como ruta a un archivo. El motivo es la
-- impresión: los documentos se arman en un iframe oculto con su propio HTML, y
-- ahí una ruta relativa depende del base de Vite y del prefijo de Nginx. Un
-- data URI no depende de nada y se imprime igual en cualquier ambiente.
-- Mismo criterio que color_marca: vive en la base, así que cargar el logo de
-- una empresa nueva es un UPDATE, sin desplegar.
ALTER TABLE core.empresas ADD COLUMN logo TEXT;

COMMENT ON COLUMN core.empresas.logo IS
  'Logo de la empresa como data URI (data:image/png;base64,...). Solo presentación: sidebar, reportes y documentos impresos. NULL = se cae al recuadro con el color de marca.';

ALTER TABLE core.empresas
  ADD CONSTRAINT ck_empresas_logo_data_uri
  CHECK (logo IS NULL OR logo LIKE 'data:image/%');

-- 2) ESPEJO A GOOGLE SHEETS ---------------------------------------------------
-- Los libros de Google Sheets que alimentan los Dashboards de Data Studio son
-- de Digitexsa. Hasta ahora el espejo corría para cualquier empresa, así que el
-- consumo de Digitalpro habría caído en los libros de Digitexsa y los
-- Dashboards lo habrían contado como propio.
--
-- El DEFAULT es false a proposito. El modo de falla de equivocarse aca no es
-- perder una fila: es CONTAMINAR los libros de produccion con datos de otra
-- empresa, y limpiarlos despues es a mano. Que una empresa nueva no espeje
-- hasta que alguien lo decida es el error barato; el caro es el contrario.
ALTER TABLE core.empresas
  ADD COLUMN espeja_sheets BOOLEAN NOT NULL DEFAULT false;

COMMENT ON COLUMN core.empresas.espeja_sheets IS
  'Si true, las reposiciones y los envios de consumo de esta empresa se replican en los Google Sheets legacy que alimentan Data Studio. Default false: una empresa nueva no escribe en libros ajenos hasta que se habilite explicitamente.';

-- Digitexsa es hoy la unica que si debe espejar (decision del usuario,
-- 2026-09-30: lo de Digitalpro se guarda solo en PostgreSQL).
UPDATE core.empresas SET espeja_sheets = true WHERE codigo = 'DIGITEXSA';

UPDATE core.empresas
   SET logo = 'data:image/png;base64,'
 WHERE codigo = 'DIGITEXSA';
